        if (is_comp[p]) continue;
        int twin = 0, sexy = 0;
        if (p >= 2 && !is_comp[p - 2]) twin = 1;
        if (!is_comp[p + 2]) twin = 1;
        if (p >= 6 && !is_comp[p - 6]) sexy = 1;
        if (!is_comp[p + 6]) sexy = 1;
        printf("  p=%lld twin=%d sexy=%d %s\n", p, twin, sexy, (twin&&sexy) ? "***" : "");
    }

    free(is_comp);
    return 0;
}
